SIMPLE = {"전화": "call", "음악": "play_music", "볼륨": "volume"}

def route(utter):
    for k, intent in SIMPLE.items():
        if k in utter and len(utter) <= 15:
            return ("NLU", intent)
    return ("LLM", None)

for u in ["엄마한테 전화해 줘", "음악 틀어 줘",
          "근처 주유소 들렀다 집에 가자", "주차 되는 조용한 카페 찾아 줘"]:
    print(u, "->", route(u))
# 엄마한테 전화해 줘 -> ('NLU', 'call')
# 음악 틀어 줘 -> ('NLU', 'play_music')
# 근처 주유소 들렀다 집에 가자 -> ('LLM', None)
# 주차 되는 조용한 카페 찾아 줘 -> ('LLM', None)
